static void transportSelectionTests(){
 using namespace TransportSelection;
 const double rate=48000;
 double marker=8;marker=nudge(marker,-1,120);marker=nudge(marker,-1,120);
 require(marker==4,"Two keypad rewinds move play start back two 4/4 bars");
 const auto p=plan(true,false,marker,8,10,0,rate);
 require(!p.error&&p.punch&&p.origin==4&&p.start==8&&p.end==10,"Dynamic selection auto-punch uses independent play start and fixed selection");
 require(std::llround((p.start-p.origin)*rate)==192000&&std::llround((p.end-p.origin)*rate)==288000,"Punch boundaries are sample-accurate offsets from playback origin");
 require(nudge(1,-1,120)==0,"Rewind clamps to session start");
 require(plan(true,false,11,8,10,0,rate).error!=nullptr,"Starting beyond punch-in is rejected");
 const auto normal=plan(false,false,4,8,10,3,rate);require(!normal.error&&!normal.punch&&normal.start==3,"Disabling Dynamic retains normal recording insertion");
 const auto noRange=plan(true,false,4,8,8,3,rate);require(!noRange.error&&!noRange.punch&&noRange.start==4,"Dynamic insertion without a range records immediately");
 require(plan(false,true,0,8,8,0,rate).error!=nullptr,"Explicit punch requires a valid range");
 for(double tempo:{88.5,120.,240.})require(std::abs(nudge(20,-1,tempo)-(20-240/tempo))<1.e-9,"Manual pre-roll follows the session tempo");
}
static void overdubTests(const juce::File& folder){
 for(bool punch:{false,true}){
  auto owner=std::make_unique<AudioEngine>();auto& e=*owner;e.playback.deviceRate=48000;e.playback.process=PluginRack::process;e.playback.processContext=&e.plugins;require(e.playback.suppressRecordedPlayback,"Recording suppresses old target audio by default");
  auto& track=e.playback.tracks[0];track.left.assign(96000,.1f);track.right=track.left;track.sourceRate=48000;track.gain=1;e.playback.refreshDuration();e.trackInputs[0]=0;e.trackInputChannels[0]=1;e.monitorLevels[0]=1;e.monitorOverrides[0]=-1;e.punchEnabled=punch;
  const auto file=folder.getChildFile(juce::String(punch?"Punch-Overdub-":"Normal-Overdub-")+juce::Uuid().toString()+".wav");require(e.recorder.startGroup({{0,0,1,file}},48000,96000).wasOk(),"Start real overdub recorder");e.playback.recording=true;e.playback.recordTrack=0;e.playback.recordTracks[0]=true;e.playback.playing=true;
  float input[512],left[512],right[512];std::fill_n(input,512,.2f);const float* in[]{input};float* out[]{left,right};for(int i=0;i<12;++i)e.renderAudio(in,1,out,2,512);require(std::abs(left[511])<.0001f,"Old target audio is silent while recording, including punch mode");
  e.monitorOverrides[0]=1;for(int i=0;i<12;++i)e.renderAudio(in,1,out,2,512);require(std::abs(left[511]-.2f)<.0001f&&track.peak.load()>.19f,"Only live input is heard on the record target and its output meter");
  auto& backing=e.playback.tracks[1];backing.left.assign(96000,.05f);backing.right=backing.left;backing.sourceRate=48000;backing.gain=1;e.playback.refreshDuration();for(int i=0;i<12;++i)e.renderAudio(in,1,out,2,512);require(std::abs(left[511]-.25f)<.0001f,"Other tracks keep playing while the old target take stays suppressed");
  e.recorder.requestStop();require(e.recorder.waitForFinish(5000),"Finish captured overdub WAV");juce::WavAudioFormat format;auto stream=file.createInputStream();std::unique_ptr<juce::AudioFormatReader> reader(format.createReaderFor(stream.release(),true));require(reader&&reader->lengthInSamples>512,"Recorded overdub WAV is readable");juce::AudioBuffer<float> recorded(1,512);reader->read(&recorded,0,512,0,true,false);require(std::abs(recorded.getSample(0,511)-.2f)<.0001f,"Recording captures the input only, without printing old playback into the new take");
 }
}
static void monitoringTests(){
 for(double tempo:{20.,88.5,300.}){SavedSession saved;saved.bpm=tempo;SessionTrack track;track.name="Tempo test";saved.tracks.push_back(track);SavedSession restored;const auto file=juce::File::getCurrentWorkingDirectory().getChildFile("work/prototype/Tempo.tracksmith");require(SessionFile::decode(SessionFile::encode(saved,file),file,restored).wasOk()&&restored.bpm==tempo,"Full session tempo range and decimal BPM save and reopen");}
 auto owner=std::make_unique<AudioEngine>();auto& e=*owner;e.playback.deviceRate=48000;e.playback.process=PluginRack::process;e.playback.processContext=&e.plugins;
 for(int i=0;i<3;++i){e.trackInputChannels[i]=1;e.trackInputs[i]=i;e.monitorOverrides[i]=1;e.monitorLevels[i]=1;e.playback.tracks[i].gain=1;}e.trackInputs[1]=2;e.monitorOverrides[2]=0;e.playback.tracks[0].pan=-1;e.playback.tracks[1].pan=1;
 float a[512],b[512],c[512],left[512]{},right[512]{};std::fill_n(a,512,.1f);std::fill_n(b,512,.2f);std::fill_n(c,512,.3f);const float* inputs[]{a,nullptr,b,c};float* outputs[]{left,right};
 auto render=[&]{for(int n=0;n<12;++n)e.renderAudio(inputs,4,outputs,2,512);};auto near=[](float a,float b){return std::abs(a-b)<.0001f;};render();require(near(left[511],.1f)&&near(right[511],.2f),"Two independent monitor tracks preserve their assigned hardware inputs and pan");require(e.playback.inputMonitorTracks[0]&&e.playback.inputMonitorTracks[1],"Both monitor tracks stay active");
 e.monitorLevels[0]=.5f;render();require(near(left[511],.05f)&&near(right[511],.2f),"Monitor levels are independent");
 e.monitorOverrides[0]=-1;e.monitorArmed=true;e.armedMonitorMask[0]=true;render();require(near(left[511],0)&&near(right[511],.2f)&&!e.wantsMonitor(0),"Disabling one monitor leaves the other on and overrides auto-arm monitoring");
 e.monitorOverrides[0]=1;e.monitorLevels[0]=1;e.playback.tracks[0].muted=true;render();require(near(left[511],0)&&near(right[511],.2f),"Live monitor tracks obey independent channel mute");e.playback.tracks[0].muted=false;
 e.monitorOverrides[2]=1;e.trackInputs[2]=2;e.trackInputChannels[2]=2;render();require(near(left[511],.3f)&&near(right[511],.5f),"Stereo input can monitor alongside two mono tracks");e.trackInputs[2]=1;render();require(!e.playback.inputMonitorTracks[2]&&near(left[511],.1f)&&near(right[511],.2f),"Unavailable stereo input does not silence other monitored tracks");
 e.monitorLevels[1]=.7f;require(TrackEditing::remove(e,0,3),"Delete monitored track");require(e.monitorOverrides[0].load()==1&&near(e.monitorLevels[0].load(),.7f)&&e.trackInputs[0].load()==2,"Track deletion moves monitoring state with its physical input assignment");e.clearTrackMonitoring();e.monitor.enabled=false;e.monitorArmed=false;render();require(!e.monitorActive.load()&&near(left[511],0)&&near(right[511],0),"Session monitoring reset is silent");
}
static void clickTests(const juce::File& folder){
 auto rack=std::make_unique<PluginRack>();rack->midiLanes[0].enabled=true;const auto desc=NativeInstruments::clickDescription();require(rack->install(0,0,desc,NativeInstruments::create(desc),{},false,48000).wasOk(),"Native mono click installs");auto* click=dynamic_cast<NativeClickProcessor*>(rack->channels[0][0]->instance.get());require(click&&rack->channels[0][0]->channels==1,"Click has one mono output");
 juce::AudioBuffer<float> block(1,256);juce::MidiBuffer midi;rack->clock.playing=false;click->processBlock(block,midi);require(block.getMagnitude(0,256)==0,"Click is silent while transport stopped");rack->clock.playing=true;rack->clock.bpm=120;rack->clock.seconds=0;click->processBlock(block,midi);const float accent=block.getMagnitude(0,256);require(accent>.01f,"Accented click sounds at transport start");
 rack->clock.seconds=24000./48000;click->processBlock(block,midi);require(block.getMagnitude(0,256)<accent,"Other beats use independent softer level");
 click->reset();rack->clock.seconds=23990./48000;click->processBlock(block,midi);require(block.getMagnitude(0,10)==0&&block.getMagnitude(11,245)>.01f,"Click crosses a block boundary at the exact beat sample");
 auto set=[&](const char* id,float value){auto* p=click->parameters.getParameter(id);p->setValueNotifyingHost(p->convertTo0to1(value));};
 set("division",1);click->reset();rack->clock.seconds=.25;click->processBlock(block,midi);require(block.getMagnitude(0,256)>.01f,"Eighth-note subdivision at tempo");
 click->transportEnabled=false;click->processBlock(block,midi);require(block.getMagnitude(0,256)==0,"Global Click switch silences native click");click->transportEnabled=true;
 set("mode",1);click->recording=false;click->processBlock(block,midi);require(block.getMagnitude(0,256)==0,"Record-only click is silent during playback");click->recording=true;click->processBlock(block,midi);require(block.getMagnitude(0,256)>.01f,"Record-only click sounds while recording");set("mode",0);
 click->offline=true;click->processBlock(block,midi);require(block.getMagnitude(0,256)==0,"Click excluded from mix export by default");set("export",1);click->processBlock(block,midi);require(block.getMagnitude(0,256)>.01f,"Explicitly include click in mix export");click->offline=false;
 juce::MemoryBlock state;click->getStateInformation(state);auto restored=NativeInstruments::create(desc);restored->setStateInformation(state.getData(),(int)state.getSize());auto* copy=dynamic_cast<NativeClickProcessor*>(restored.get());require(copy&&copy->parameters.getRawParameterValue("division")->load()==1&&copy->parameters.getRawParameterValue("export")->load()==1,"Click settings restore in native session state");
 std::unique_ptr<juce::AudioProcessorEditor> editor(click->createEditor());snapshot(*editor,folder.getChildFile("Tracksmith-Click.png"));
 auto playback=std::make_unique<PlaybackCore>();playback->deviceRate=48000;playback->tracks[0].midiTrack=true;playback->tracks[0].midiSeconds=1;playback->tracks[0].gain=1;playback->metronome=true;playback->refreshDuration();rack->rebuildCompensation(*playback);require(playback->nativeClickTrackPresent.load(),"Dedicated click suppresses legacy master click");playback->process=PluginRack::process;playback->processContext=rack.get();playback->playing=true;
 float left[256]{},right[256]{};float* out[]{left,right};playback->render(out,2,256);require(juce::FloatVectorOperations::findMinAndMax(left,256).getEnd()>.001f,"Click reaches track mixer output");
 playback->tracks[0].muted=true;playback->primeMixLevels();playback->seekSeconds=0;playback->render(out,2,256);require(juce::FloatVectorOperations::findMinAndMax(left,256).getEnd()==0,"Track mute silences click without master fallback");playback->tracks[0].muted=false;rack->channels[0][0]->bypass=true;playback->seekSeconds=0;playback->render(out,2,256);require(juce::FloatVectorOperations::findMinAndMax(left,256).getEnd()==0,"Click insert bypass does not reveal a doubled master click");
 rack->channels[0][0]->bypass=false;playback->seekSeconds=2;playback->render(out,2,256);require(playback->playing.load(),"Click-only playback continues past empty instrument length");
 playback->tracks[0].muted=false;playback->primeMixLevels();MixExportOptions exportOptions;exportOptions.start=0;exportOptions.end=1;exportOptions.tail=0;
 for(bool include:{false,true}){set("export",include?1:0);const auto file=folder.getChildFile(include?"Click-Included.wav":"Click-Excluded.wav");const auto result=writeMixWav(*playback,file,exportOptions,[]{return false;},[](double){});require(result.error.isEmpty(),"Click mix export completes");juce::WavAudioFormat format;auto input=file.createInputStream();std::unique_ptr<juce::AudioFormatReader> reader(format.createReaderFor(input.release(),true));require(reader!=nullptr,"Read click bounce");juce::AudioBuffer<float> rendered(2,(int)reader->lengthInSamples);reader->read(&rendered,0,rendered.getNumSamples(),0,true,true);require(include?rendered.getMagnitude(0,rendered.getNumSamples())>.01f:rendered.getMagnitude(0,rendered.getNumSamples())==0,"Mix bounce honors explicit click inclusion");}

}
static void wav(const juce::File& file,const juce::AudioBuffer<float>& audio){juce::WavAudioFormat format;std::unique_ptr<juce::OutputStream> out=file.createOutputStream();auto writer=format.createWriterFor(out,juce::AudioFormatWriterOptions().withSampleRate(48000).withNumChannels(audio.getNumChannels()).withBitsPerSample(24));require(writer&&writer->writeFromAudioSampleBuffer(audio,0,audio.getNumSamples()),"WAV fixture");}
static void snapshot(juce::Component& editor,const juce::File& file){juce::Timer::callPendingTimersSynchronously();auto out=file.createOutputStream();require(out!=nullptr,"Snapshot file");out->setPosition(0);out->truncate();juce::PNGImageFormat png;require(png.writeImageToStream(editor.createComponentSnapshot(editor.getLocalBounds()),*out),"Snapshot render");}
